fn binary_search_gene_exons(gene_exons: &Vec<(usize, usize)>, target_start: usize, target_end: usize) -> Option<usize> {
    use std::cmp::Ordering;

    let mut size = gene_exons.len();
    if size == 0 {
        return None;
    }
    let mut base = 0_usize;

    while size > 1 {
        let half = size / 2;
        let mid = base + half;
        if gene_exons[mid].0 <= target_start {
            base = mid;
